bool tile_feat_index(const char *str, tileidx_t *idx)
{
    ASSERT(str);
    if (!str)
        return false;

    string lc = str;
    for (unsigned int i = 0; i < lc.size(); i++)
        lc[i] = toalower(lc[i]);

    int num_pairs = sizeof(feat_name_pairs) / sizeof(feat_name_pairs[0]);
    bool result = binary_search<const char *, tileidx_t>(
       lc.c_str(), &feat_name_pairs[0], num_pairs, &strcmp, idx);
    return result;
}

bool tile_feat_equal(tileidx_t tile, tileidx_t idx)
{
    ASSERT_RANGE(tile, TILE_WALL_MAX, TILE_FEAT_MAX);
    return idx >= tile && idx < tile + tile_feat_count(tile);
}


typedef pair<tile_variation, tileidx_t> _variation_pair;

static _variation_pair feat_colour_pairs[] =
{
    _variation_pair(tile_variation(0, 0), 0),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 1), 27 + TILE_WALL_MAX),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 4), 19 + TILE_WALL_MAX),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 6), 22 + TILE_WALL_MAX),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 9), 31 + TILE_WALL_MAX),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 12), 17 + TILE_WALL_MAX),
    _variation_pair(tile_variation(0 + TILE_WALL_MAX, 14), 13 + TILE_WALL_MAX),
    _variation_pair(tile_variation(582 + TILE_WALL_MAX, 15), 583 + TILE_WALL_MAX),
};

tileidx_t tile_feat_coloured(tileidx_t idx, int col)
{
    int num_pairs = sizeof(feat_colour_pairs) / sizeof(feat_colour_pairs[0]);
    tile_variation key(idx, col);
    tileidx_t found;
    bool result = binary_search<tile_variation, tileidx_t>(
       key, &feat_colour_pairs[0], num_pairs,
       &tile_variation::cmp, &found);
    return (result ? found : idx);
}

static _variation_pair feat_enchant_pairs[] =
{
    _variation_pair(tile_variation(0, 0), 0),
};

tileidx_t tile_feat_enchanted(tileidx_t idx, int ench)
{
    int num_pairs = sizeof(feat_enchant_pairs) / sizeof(feat_enchant_pairs[0]);
    tile_variation key(idx, ench);
    tileidx_t found;
    bool result = binary_search<tile_variation, tileidx_t>(
       key, &feat_enchant_pairs[0], num_pairs,
       &tile_variation::cmp, &found);
    return (result ? found : idx);
}

